(function(root){'use strict';
let lastRun='',seen=-1,trauma=0,flash=0,cutin=null;const particles=[],trails=new Map();
function observe(game){if(lastRun!==game.runId){seen=-1;lastRun=game.runId;particles.length=0;trails.clear();cutin=null;trauma=0;}for(const f of game.fx){if(f.id<=seen)continue;seen=Math.max(seen,f.id);if(['hit','hurt','death','impact','ultimate'].includes(f.type)){const count=f.type==='ultimate'?50:f.type==='impact'?24:12;for(let i=0;i<count&&particles.length<220;i++){const angle=(i*2.399+f.id),speed=70+(i%7)*35;particles.push({x:f.x,y:f.y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed-65,life:.25+(i%5)*.09,max:.61,color:f.color||'#ff8066',size:i%4===0?5:2});}trauma=Math.max(trauma,f.type==='ultimate'?12:f.type==='impact'?6:f.type==='hurt'?4:2.5);if(f.type==='ultimate'){flash=.14;cutin={cls:f.cls,life:.7,name:root.Rift.CLASSES[f.cls].skills[5].name,color:f.color};}}}}
function update(dt){trauma=Math.max(0,trauma-dt*23);flash=Math.max(0,flash-dt);if(cutin){cutin.life-=dt;if(cutin.life<=0)cutin=null;}for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;if(p.life<=0){particles.splice(i,1);continue;}p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=270*dt;}}
function actorTrail(c,p,x,y,height,dir,time,camera=0){const key=p.id+':'+p.cls,pose=root.DungeonMotion.pose(p,time),state=trails.get(key)||{points:[],step:0};state.points=state.points.filter(q=>time-q.time<.13);if(state.points.length&&Math.hypot(state.points.at(-1).x-x,state.points.at(-1).y-y)>280)state.points=[];if(p.action==='run'&&time-state.step>.2){state.step=time;for(let i=0;i<3&&particles.length<220;i++)particles.push({x:x+camera+(i-1)*12,y:y-3,vx:-dir*(15+i*8),vy:-15-i*6,life:.22,max:.22,color:'#a99a7c',size:2+i});}if(['attack','dash'].includes(pose.state)&&pose.progress>.12&&pose.progress<.86){const tips=[[218,25],[230,15],[228,205],[241,124]],tip=tips[p.cls],pivot=[[134,231],[142,265],[192,163],[183,162]][p.cls],a=pose.armR,b=pose.body,px=pivot[0]+(tip[0]-pivot[0])*Math.cos(a)-(tip[1]-pivot[1])*Math.sin(a),py=pivot[1]+(tip[0]-pivot[0])*Math.sin(a)+(tip[1]-pivot[1])*Math.cos(a),dx=px-143,dy=py-288,xx=143+dx*Math.cos(b)-dy*Math.sin(b),yy=288+dx*Math.sin(b)+dy*Math.cos(b);state.points.push({x:x+dir*(xx-128)*height/512,y:y+(yy-512+pose.y)*height/512,time});}if(state.points.length>1){c.save();c.globalCompositeOperation='lighter';c.strokeStyle=root.Rift.CLASSES[p.cls].color;c.lineCap='round';for(let i=1;i<state.points.length;i++){const a=state.points[i-1],b=state.points[i];c.globalAlpha=i/state.points.length*.48;c.lineWidth=2+i/state.points.length*8;c.beginPath();c.moveTo(a.x,a.y);c.lineTo(b.x,b.y);c.stroke();}c.restore();}trails.set(key,state);if(trails.size>16)trails.delete(trails.keys().next().value);}
function shard(c,x,y,size,color,rotation=0){c.save();c.translate(x,y);c.rotate(rotation);c.fillStyle=color;c.beginPath();c.moveTo(0,-size);c.lineTo(size*.35,0);c.lineTo(0,size*.35);c.lineTo(-size*.35,0);c.closePath();c.fill();c.strokeStyle='#fff1ddaa';c.lineWidth=1;c.stroke();c.restore();}
function arc(c,r,start,end,color,width,squeeze=.55){c.save();c.scale(1,squeeze);c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.beginPath();c.arc(20,0,r,start,end);c.stroke();c.restore();}
function effect(c,f,camera,time){if(['text','windup'].includes(f.type))return false;const age=1-f.life/(f.type==='ultimate'?1.15:.55),a=Math.min(1,f.life*4),range=f.range||140,color=f.color||'#f77c59',dir=f.dir||1;c.save();c.translate(f.x-camera,f.y-72);c.scale(dir,1);c.globalAlpha=a;c.globalCompositeOperation='lighter';
 if(f.cls===3&&f.type==='basic'){const end=(f.range||450)*Math.min(1,age*3),g=c.createLinearGradient(0,0,end+40,0);g.addColorStop(0,'#b899ff11');g.addColorStop(1,'#fff4ff');c.strokeStyle=g;c.lineWidth=5;c.beginPath();c.moveTo(0,0);c.lineTo(end,0);c.stroke();shard(c,end,0,15,'#d7b3ff',Math.PI/2);for(let i=0;i<2;i++){c.strokeStyle=color;c.lineWidth=2;c.beginPath();c.ellipse(8,0,12+age*20,22+age*25,0,0,Math.PI*2);c.stroke();}}
 else if(f.cls===2&&['basic','cone','rush'].includes(f.type)){const end=Math.min(range,260)*(.3+age*.5);c.strokeStyle='#fff2d3';c.lineWidth=8*(1-age)+2;c.beginPath();c.moveTo(-25,-15);c.quadraticCurveTo(end*.6,-35,end,0);c.stroke();for(let i=0;i<7;i++)shard(c,end+(i%3)*12,(i-3)*13*(.3+age),12*(1-age)+3,color,i*.8);arc(c,45+age*65,-1.35,1.35,color,3,.8);}
 else if(['basic','cone','lift'].includes(f.type)){const radius=Math.min(330,range)*(.7+age*.4),turn=(f.combo%2?1:-1);c.rotate(f.type==='lift'?-1.1:turn*(-.45+age*.8));for(let i=4;i>=0;i--)arc(c,radius-i*5,-1.45+age*.6,1.25,color,i===0?3:10-i,.6);arc(c,radius-12,-1.35,1.1,'#fff4dc',3);for(let i=0;i<7;i++){c.fillStyle=color;c.fillRect(50+i*23,-30+(i%3)*24,30+age*40,2);}if(f.cls===0){for(let i=0;i<10;i++){const t=-1.2+i*.25;shard(c,20+Math.cos(t)*radius,Math.sin(t)*radius*.6,8+(i%3)*4,color,t+age*2);}}else if(f.cls===1){for(let i=0;i<6;i++)shard(c,20+Math.cos(i*.4-1)*radius,Math.sin(i*.4-1)*radius*.6,13,color,i);}}
 else if(['line','chain'].includes(f.type)){const end=range*(.55+age*.45),w=(1-age)*26+3,g=c.createLinearGradient(0,0,end,0);g.addColorStop(0,color);g.addColorStop(.8,'#fff8ed');g.addColorStop(1,'#ffffff00');c.fillStyle=g;c.beginPath();c.moveTo(0,-w);c.lineTo(end+50,0);c.lineTo(0,w);c.fill();c.strokeStyle='#fff9ee';c.lineWidth=3;c.beginPath();c.moveTo(0,0);if(f.type==='chain')for(let i=1;i<12;i++)c.lineTo(end*i/12,Math.sin(i*7+f.id)*23*(1-age));c.lineTo(end,0);c.stroke();for(let i=0;i<5;i++){c.strokeStyle=color;c.lineWidth=2;c.beginPath();c.ellipse(end*i/5,0,13+age*15,30+age*20,0,0,Math.PI*2);c.stroke();}if(f.cls===1&&f.index===4){for(let i=1;i<9;i++)shard(c,end*i/9,Math.sin(i*2)*20,20*(1-age)+8,'#9beaf4',Math.PI/5);}}
 else if(['circle','pull','ultimate','impact'].includes(f.type)){c.translate(0,65);const r=range*(.3+age*.75);for(let i=0;i<3;i++){c.strokeStyle=i===1?'#fff0cb':color;c.lineWidth=i===1?2:7;c.beginPath();c.ellipse(0,0,r+i*14,(r+i*14)*.34,0,0,Math.PI*2);c.stroke();}for(let i=0;i<12;i++){const t=i*Math.PI/6+age*(f.type==='pull'?-2:1),x=Math.cos(t)*r,y=Math.sin(t)*r*.34;c.save();c.translate(x,y);c.rotate(t);c.fillStyle=color;c.beginPath();c.moveTo(-7,0);c.lineTo(0,-35*(1-age)-8);c.lineTo(7,0);c.fill();c.restore();}if(f.cls===0&&f.type!=='impact'){for(let i=0;i<9;i++){const xx=(i-4)*r/5,yy=Math.sin(i*3)*r*.2;shard(c,xx,yy-30*age,24*(1-age)+12,color,Math.sin(i)*.3);}}else if(f.cls===1){for(let i=0;i<9;i++){const t=i*Math.PI*2/9;shard(c,Math.cos(t)*r*.7,Math.sin(t)*r*.25,45*(1-age)+8,'#a9f5ff',Math.sin(t)*.5);}}else if(f.cls===2){for(let i=0;i<8;i++){c.save();c.translate((i-3.5)*r/5,Math.sin(i)*20-age*60);c.rotate(i*.7);c.fillStyle=i%2?'#e5c17b':'#847367';c.fillRect(-7,-10,14,20);c.restore();}}else if(f.cls===3){c.save();c.rotate(age*2);for(let i=0;i<6;i++){const t=i*Math.PI/3;shard(c,Math.cos(t)*r*.65,Math.sin(t)*r*.22,18,color,t);}c.restore();}if(f.caster){c.fillStyle='#d3b8ff';c.globalAlpha=a*.55;const g=c.createLinearGradient(0,-130,0,30);g.addColorStop(0,'#b999ff00');g.addColorStop(.8,'#bd9aff99');g.addColorStop(1,'#f2eaff');c.fillStyle=g;c.fillRect(-18*(1-age),-170,36*(1-age),190);}
 if(f.type==='ultimate'){for(let i=0;i<9;i++){const x=(i-4)*range/5;c.fillStyle=i%2?color:'#fff6dc';c.globalAlpha=a*.55;c.fillRect(x,-500*(1-age),4+i%3*6,520*(1-age));}}}
 else if(['dash','rush'].includes(f.type)){for(let i=0;i<9;i++){c.globalAlpha=a*(1-i/10);c.fillStyle=i%2?color:'#fff5db';c.fillRect(-220+age*120-i*18,-100+i*23,150+i*14,2+i%3);}}
 else if(['shield','heal'].includes(f.type)){for(let i=0;i<3;i++){c.strokeStyle=color;c.lineWidth=2;c.beginPath();c.ellipse(0,-10,62+i*9+age*18,105+i*11,0,-Math.PI*age,Math.PI*(2-age));c.stroke();}if(f.type==='heal'){c.fillStyle='#a4f8c3';for(let i=0;i<6;i++){const x=Math.sin(i*8)*55,y=20-i*25-age*80;c.fillRect(x-3,y-9,6,18);c.fillRect(x-9,y-3,18,6);}}}
 else if(['hit','hurt','death'].includes(f.type)){const r=13+(1-age)*8,g=c.createRadialGradient(0,0,0,0,0,r*2);g.addColorStop(0,'#fffce7');g.addColorStop(.25,color);g.addColorStop(1,'#ffffff00');c.fillStyle=g;c.fillRect(-r*2,-r*2,r*4,r*4);for(let i=0;i<5;i++)shard(c,Math.cos(i*2.4)*(12+age*28),Math.sin(i*2.4)*(12+age*28),10*(1-age)+2,color,i*2.4);}

 else{c.restore();return false;}c.restore();return true;}
function overlay(c,camera,images){c.save();c.globalCompositeOperation='lighter';for(const p of particles){c.globalAlpha=Math.max(0,p.life/p.max);c.fillStyle=p.color;c.save();c.translate(p.x-camera,p.y);c.rotate(Math.atan2(p.vy,p.vx));c.fillRect(-p.size,-1,p.size*3,2);c.restore();}c.restore();if(flash>0){c.fillStyle='rgba(255,242,218,'+flash*2+')';c.fillRect(0,0,1600,800);}if(cutin){const t=cutin.life,slide=Math.min(1,(.7-t)*12),x=-460+(slide*460);c.save();c.globalAlpha=Math.min(1,t*4);c.fillStyle='#0a101eed';c.beginPath();c.moveTo(x,112);c.lineTo(x+560,112);c.lineTo(x+515,212);c.lineTo(x,212);c.fill();c.fillStyle=cutin.color;c.fillRect(x,211,515,2);if(images.fighters){const im=images.fighters,sw=im.width/4;c.save();c.beginPath();c.rect(x,112,230,100);c.clip();c.drawImage(im,sw*cutin.cls,0,sw,im.height,x+5,50,240,480);c.restore();}c.font='700 24px "Rift UI",sans-serif';c.fillStyle='#fff1d3';c.textAlign='left';c.fillText(cutin.name,x+235,173);c.restore();}}
root.DungeonEffects={observe,update,actorTrail,effect,overlay,shake:time=>root.DungeonSound.settings().shake?[Math.sin(time*83)*trauma,Math.cos(time*91)*trauma*.6]:[0,0],stats:()=>({particles:particles.length,trauma})};
})(window);
